import { defaults, type PushOptions } from './defaults.js';
 import { destinations } from './destinations.js';
 export function resolvePush(env: Record<string, string | undefined>, target: string, patch: Partial<PushOptions>) {
   const global = { ...defaults, waitMs: Number(env.TILE_WAIT_MS ?? defaults.waitMs) };
   const policy = destinations[target] ?? {};
   const selected = {
     ...global,
     ...(policy.waitSeconds === undefined ? {} : { waitMs: Math.round(policy.waitSeconds * 1000) }),
     ...(policy.parallel === undefined ? {} : { parallel: policy.parallel })
   };
   return { ...selected, ...patch };
 }

